const load = () => {
    fetch('/api/entries', {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
        },
    }).then((response) => {
        if (response.ok) {
            response.json().then((data) => {
                setEntries(data);
            });
        } else {
            setEntries([]);
        }
    });
};
