def summarize(payload):

    total_minutes = 0
    by_project = {}
    by_day = {}
    active_projects = 0
    busiest_day = None
    for entry in payload['entries']:
        if entry['project'] not in by_project:
            by_project[entry['project']] = 1
        else:
            by_project[entry['project']] += 1
        if entry['date'] not in by_day:
            by_day[entry['date']] = 1
        else:
            by_day[entry['date']] += 1
        if entry['project'] not in active_projects:
            active_projects += 1
        if entry['date'] not in busiest_day:
            busiest_day = entry['date']
        else:
            if busiest_day > entry['date']:
                busiest_day = entry['date']
    return {'total_minutes': total_minutes, 'by_project': by_project, 'by_day': by_day, 'active_projects':
            active_projects, 'busiest_day': busiest_day}

