            const projectId = projectString.toUpperCase();
            const minutesInMinutes = minutesString;
            const dateInISO = dateString;
            const noteInMarkdown = noteString;
            const { id } = form;
            const entriesToAdd = [{
                project: projectId,
                minutes: minutesInMinutes,
                date: dateInISO,
                note: noteInMarkdown,
            }];
            const newEntries = entries.concat(entriesToAdd);
            const newEntriesWithId = newEntries.map((entry) => ({
                ...entry,
                id,
            }));
            setEntries(newEntriesWithId);
            setForm({ project: '', minutes: '', date: '', note: '' });
            load();
        }
        else {
            setForm({ project: '', minutes: '', date: '', note: '' });
        }
    };
    const handleAdd = (e) => {
        e.preventDefault();
        const { id } = form;
